// Helpers for solver.mjs: id normalisation, time, edition choice, table loading.
// Everything here is pure; time only comes from the input.

export const MIN = 60_000;

export function normId(raw) {
  if (raw === null || raw === undefined) return null;
  let s = String(raw).trim();
  if (s.startsWith('#')) s = s.slice(1).trim();
  return s.toUpperCase();
}

export function ms(iso) {
  return Date.parse(iso);
}

// Edition in force at p: latest effectiveFrom on or before the date of p (Europe/Amsterdam).
export function localDate(iso) {
  // Dates in the spec carry an offset; the calendar day is the Amsterdam day.
  const d = new Date(ms(iso));
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Europe/Amsterdam', year: 'numeric', month: '2-digit', day: '2-digit',
  }).format(d);
  return parts; // YYYY-MM-DD
}

export function pickEdition(editions, placedAt) {
  const day = localDate(placedAt);
  const ok = editions
    .filter(e => e && typeof e.effectiveFrom === 'string' && e.effectiveFrom.slice(0, 10) <= day)
    .sort((a, b) => (a.effectiveFrom < b.effectiveFrom ? 1 : -1));
  return ok.length ? ok[0] : null;
}

// Parse a rulebook/master file. JSON arrays and objects are returned as-is;
// CSV is turned into an array of row objects keyed by header name.
export function parseFile(name, text) {
  if (text === undefined || text === null) return null;
  if (name.endsWith('.csv')) {
    const lines = text.split(/\r?\n/).filter(l => l.trim() !== '');
    if (!lines.length) return [];
    const head = lines[0].split(',').map(h => h.trim());
    return lines.slice(1).map(l => {
      const cells = l.split(',').map(c => c.trim());
      const row = {};
      head.forEach((h, i) => {
        const v = cells[i];
        row[h] = v !== undefined && v !== '' && !isNaN(Number(v)) ? Number(v) : v;
      });
      return row;
    });
  }
  return JSON.parse(text);
}

// Rows of a table: a bare array, or the first array-valued property of an object.
export function rowsOf(doc) {
  if (Array.isArray(doc)) return doc;
  if (doc && typeof doc === 'object') {
    for (const v of Object.values(doc)) if (Array.isArray(v)) return v;
  }
  return [];
}

// Find a value by any of several candidate field names (case-insensitive).
export function field(row, names) {
  if (!row || typeof row !== 'object') return undefined;
  const keys = Object.keys(row);
  for (const n of names) {
    const hit = keys.find(k => k.toLowerCase() === n.toLowerCase());
    if (hit !== undefined) return row[hit];
  }
  return undefined;
}

// Map a carrier code to one meaning; unknown codes are `info`.
const MEANINGS = ['collected', 'inTransit', 'delivered', 'collectionFailed', 'info'];
export function meaningOf(rows, code) {
  for (const r of rows) {
    const c = field(r, ['code', 'carrierCode', 'carrier_code']);
    if (c !== undefined && String(c) === String(code)) {
      const m = field(r, ['meaning', 'status', 'means', 'kind', 'class', 'meaningKey']);
      if (m !== undefined && MEANINGS.includes(String(m))) return String(m);
    }
  }
  return 'info';
}

